<script setup lang="ts">
/**
 * Vertical layout primitive (`design/components/stack.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/stack.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */

import { spacingAttrs, type LayoutPatch, type SpaceStep } from '@polymorph/vue'
import styles from '@polymorph/recipes/layout/layout.module.css'

export type StackAlign = NonNullable<StackProps['align']>

export type StackElement = NonNullable<StackProps['as']>

export type StackJustify = NonNullable<StackProps['justify']>

export interface StackProps {
  align?: 'stretch' | 'start' | 'center' | 'end'
  /**
   * List and form semantics without a wrapper element.
   */
  as?: 'form' | 'div' | 'section' | 'ul' | 'ol'
  gap?: SpaceStep
  justify?: 'start' | 'center' | 'end' | 'between'
  p?: SpaceStep
  patch?: LayoutPatch
  px?: SpaceStep
  py?: SpaceStep
}

defineOptions({ name: 'Stack', inheritAttrs: false })

withDefaults(defineProps<StackProps>(), { align: 'stretch', as: 'div', justify: 'start' })
defineSlots<{ default?: (props: Record<string, never>) => unknown }>()
</script>

<template>
  <component
    :is="as"
    v-bind="spacingAttrs({ gap, p, px, py, patch })"
    :class="[styles.layout, styles.stack]"
    :data-align="align"
    :data-justify="justify"
    data-member="stack"
  >
    <slot />
  </component>
</template>
